StringJoiner sj = new StringJoiner(", ", "[", "]");
sj.add("RELIANCE").add("TCS").add("HDFC");
String result = sj.toString();  // "[RELIANCE, TCS, HDFC]"

// setEmptyValue: override output for empty joiner
StringJoiner empty = new StringJoiner(", ", "[", "]");
empty.setEmptyValue("NO SYMBOLS");
empty.toString();  // "NO SYMBOLS" (not "[]")

// ═══ String.join — static shortcut (no prefix/suffix) ═══
String csv = String.join(", ", "RELIANCE", "TCS", "HDFC");  // "RELIANCE, TCS, HDFC"
String fromList = String.join(", ", List.of("RELIANCE", "TCS"));  // "RELIANCE, TCS"

// ═══ Collectors.joining — stream collector ═══
String stream = Stream.of("RELIANCE", "TCS", "HDFC")
    .collect(Collectors.joining(", ", "[", "]"));  // "[RELIANCE, TCS, HDFC]"

// ═══ RELATIONSHIP ═══
// String.join → uses StringJoiner internally (no prefix/suffix)
// Collectors.joining → uses StringJoiner internally (with prefix/suffix)
// StringJoiner → used directly for imperative control
