package com.bank.joiner;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class StringJoinerTest {

    @Test void basicJoiner() {
        StringJoiner sj = new StringJoiner(", ");
        sj.add("A").add("B").add("C");
        assertThat(sj.toString()).isEqualTo("A, B, C");
    }

    @Test void joinerWithPrefixSuffix() {
        StringJoiner sj = new StringJoiner(", ", "[", "]");
        sj.add("A").add("B");
        assertThat(sj.toString()).isEqualTo("[A, B]");
    }

    @Test void emptyJoinerReturnsEmptyValue() {
        StringJoiner sj = new StringJoiner(", ", "[", "]");
        sj.setEmptyValue("EMPTY");
        assertThat(sj.toString()).isEqualTo("EMPTY");  // not "[]"!
    }

    @Test void stringJoinStatic() {
        assertThat(String.join(", ", "A", "B", "C")).isEqualTo("A, B, C");
        assertThat(String.join(", ", List.of("A", "B"))).isEqualTo("A, B");
    }

    @Test void collectorsJoiningUsesStringJoiner() {
        String result = Stream.of("A", "B").collect(Collectors.joining(", ", "(", ")"));
        assertThat(result).isEqualTo("(A, B)");
    }

    @Test void mergeJoiners() {
        StringJoiner sj1 = new StringJoiner(", ");
        sj1.add("A").add("B");
        StringJoiner sj2 = new StringJoiner(", ");
        sj2.add("C").add("D");
        sj1.merge(sj2);  // merge WITHOUT prefix/suffix of sj2
        assertThat(sj1.toString()).isEqualTo("A, B, C, D");
    }
}
