package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.StringJoiner;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.assertThat;

class StringJoinerTest {

    @Test
    void joinerAndCollectorsJoiningMatch() {
        List<String> ids = List.of("SAV2001", "CUR3001", "FD4001");

        StringJoiner sj = new StringJoiner(", ", "[", "]");
        ids.forEach(sj::add);

        String viaCollector = ids.stream().collect(Collectors.joining(", ", "[", "]"));

        assertThat(sj.toString()).isEqualTo("[SAV2001, CUR3001, FD4001]");
        assertThat(viaCollector).isEqualTo(sj.toString());   // same result
    }
}
